export type BUCampusSpace = {id:string;name:string;x:number;z:number;width:number;depth:number;yaw:number;kind:'soccer'|'field-hockey'|'softball';source:string};
export const BU_FULL_SPACES: BUCampusSpace[] = [{"id":"nickerson","name":"Nickerson Field","width":106.07,"depth":65.84,"yaw":0.57,"kind":"soccer","source":"BU Athletics pitch dimensions; centre/orientation interpreted from BU 2012 aerial site plan","x":-2232.965,"z":642.358},{"id":"new-balance","name":"New Balance Field / Langsam Garage","width":130,"depth":82,"yaw":-0.155,"kind":"field-hockey","source":"BU New Balance Field 2012 PNF, field/parking level plans; footprint fitted inside MassDOT Babcock/Alcorn/Gardner/Ashford centre lines","x":-2456.244,"z":641.129},{"id":"softball","name":"BU Softball Field","width":74,"depth":72,"yaw":-0.155,"kind":"softball","source":"BU campus map and 2012 PNF aerial, approximate play area","x":-2644.161,"z":625.298}];

/** Actual footprints, including courtyards, with optional walking clearance. */
export function isInsideBUCampusBuilding(x:number,z:number,padding=0):boolean {
  const inside=(ring:WorldPoint[])=>{let hit=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;};
  return BU_FULL_BUILDINGS.some(b=>{
    if(Math.hypot(x-b.x,z-b.z)>Math.hypot(b.width,b.depth)/2+padding+2)return false;
    if(inside(b.footprint)&&!(b.holes??[]).some(inside))return true;
    if(padding<=0)return false;
    return [b.footprint,...(b.holes??[])].some(r=>r.some((a,i)=>{const c=r[(i+1)%r.length],dx=c[0]-a[0],dz=c[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz||1)));return Math.hypot(x-a[0]-t*dx,z-a[1]-t*dz)<padding;}));
  });
}
